# =====================================================================
# THE CELLS OF CHAPTERS 20-21 (first half) — F4 the siege (20:10-20), F5 the broken-necked heifer (21:1-9), F6 the captive (21:10-14) (each ask a case; the verdicts DATA rows or PARAMETERS)
# =====================================================================
def the_siege(case, data):
    """F4 — Deut 20:10-20 — THREE LINES: siege_law_declared (20:10-15) writing peace_call_commanded, tribute_service_commanded, siege_males_smitten_commanded, spoil_permitted and far_cities_scope_declared (STATUSES); seven_nations_herem_declared (20:16-18 — herem is the ban) writing nothing_alive_left_commanded (a STATUS) and abominations_teaching_barred (a BLOCK); siege_trees_declared (20:19-20) writing fruit_tree_cutting_barred (a BLOCK) and siege_works_permitted (a STATUS); Sihon's messengers by CALL (opening_speech), Midian's war by CALL (midian), the seven and the ban by CALL (seven_nations), 18:9's learning by CALL (courts_prophet); THE RECEIPT 20:17 a run citation behind (nations_devoted at 7:1)"""
    del P_[:]
    ask = case['ask']
    if ask == 'call_to_it_for_peace':
        ink('20:10', '"WHEN YOU DRAW NEAR TO A CITY TO FIGHT AGAINST IT, YOU SHALL CALL TO IT FOR PEACE" — "and you shall call to it for peace" the Bible\'s one seat (the reading\'s formula assert); "peace" in the book at 20:10, 20:11, 29:18 and 2:26 (Sihon\'s "words of peace" — the reading\'s lemma assert)')
        move('the Sifrei 199:1-5 (read whole at the reading; 199:5 REREAD from chapters 1-3); cold_run_opening_speech (CALL) — OP.the_bypass(sihon_commanded) = %s, (the_speech_resumed) = %s' % (OP_SIHON[1], OP_RESUMED[1]), "'WHEN YOU DRAW NEAR TO A CITY' — the optional war, not the seven nations' (199:1-4: the peace call's scope); GREAT IS PEACE — even in war the call first; Sihon's messengers: Deuteronomy 2:26's 'words of peace' retells Numbers 21:21's act (the tape's messengers_sent_to_sihon at Numbers 21:21-22 and sihon_war_commanded at 2:24-25 THE READBACK'S REFERENCES — opening_speech by CALL); the call three days before (199:5 — the English's note)")
        dat("THE WRITE peace_call_commanded — a STATUS on israel_people at the chapters' own day (DJ2); THE PARAMETER the_peace_calls_scope (199:1-4 — the optional war; the seven by 20:15-16's exception disputed); the exam's person the commander who besieges a far city without the call — barred from it")
        return out("call to it for peace (20:10) — the call first, great is peace; Sihon's messengers the tape's own act (the Sifrei 199:1-5; opening_speech's %s by CALL): THE WRITE peace_call_commanded, a STATUS on Israel at the chapters' own day; the commander who besieges without the call barred from it" % (OP_SIHON[1][0],), ['peace_call_commanded'])
    if ask == 'tribute_and_servitude_both':
        ink('20:11', '"AND IF IT ANSWERS YOU PEACE and opens to you, then all the people found in it SHALL BE TRIBUTARY TO YOU AND SERVE YOU" — "tributary and serve you" the Bible\'s one seat (the reading\'s formula assert); the tribute of Numbers 31:28 a different noun (the levy on the spoil)')
        move('the Sifrei 200:1-3 (read whole at the reading); cold_run_midian (CALL) — MD.the_division(tribute_rate) = %s' % (MD_RATE[1],), "'TRIBUTARY AND SERVE YOU' — both: if they accept the tribute and not the servitude, or the servitude and not the tribute, do not hearken to them until they accept both (200:1-2); Solomon's levy of the remaining nations (1 Kings 9:21 — the Prophets' run citation ahead; 200:3); Numbers 31:28's 'tribute' one of five hundred on the spoil — a different noun and a different thing (midian by CALL: the two tributes a DATA row)")
        dat("THE WRITE tribute_service_commanded — a STATUS on israel_people at the chapters' own day (DJ2); the two tributes a DATA row (the city's and the spoil's); the exam's person the city that accepts the tribute and refuses the servitude — not hearkened to: barred from the peace")
        return out("tribute and servitude both (20:11) — neither without the other; Solomon's levy ahead; the spoil's tribute a different noun (the Sifrei 200:1-3; midian's %s by CALL): THE WRITE tribute_service_commanded, a STATUS on Israel at the chapters' own day; the city that accepts one without the other barred from the peace" % (MD_RATE[1][0],), ['tribute_service_commanded'])
    if ask == 'the_siege_and_the_males':
        ink('20:12-14', '"AND IF IT WILL NOT MAKE PEACE WITH YOU BUT MAKE WAR against you, then you shall besiege it; and when the LORD your God gives it into your hand, YOU SHALL SMITE EVERY MALE OF IT by the edge of the sword; ONLY THE WOMEN AND THE LITTLE ONES and the cattle and all that is in the city, all its spoil, YOU SHALL TAKE AS PLUNDER for yourself, and you shall eat the spoil of your enemies" — "smite every male of it" the Bible\'s one seat; "the women and the little ones" at 20:14 and 3:6 (the reading\'s formula assert); taken_captive THREE and spoil_taken TWO THE TAPE\'S REFERENCES (Numbers 31:9-12\'s line the readback\'s)')
        move('the Sifrei 200:4-7, 201:1-2 (read whole at the reading); cold_run_midian (CALL) — MD.the_war(every_male) = %s, (captives) = %s, (spoil) = %s, MD.the_sentence(every_female_kept) = %s, (deuteronomy_20) = %s' % (MD_MALE[1], MD_CAPT[1], MD_SPOIL[1], MD_FEMALE[1], MD_D20[1]), "'IF IT WILL NOT MAKE PEACE BUT WAR' — even then, the call was owed (200:4); 'WHEN THE LORD GIVES IT INTO YOUR HAND' — the siege's end His, not the sword's (200:5); 'SMITE EVERY MALE' — the males, not the women and the little ones (200:6-7); 'ONLY THE WOMEN AND THE LITTLE ONES' — Numbers 31:17's 'every male among the little ones' STRICTER than this chapter (midian's own ask deuteronomy_20 read at the callees: 'spares the women and the little ones — this chapter stricter on both; NOT COMPILED, owed at its chapter' — PAID HERE); 'YOU SHALL EAT THE SPOIL' — the spoil permitted (201:1-2)")
        dat("THE WRITES siege_males_smitten_commanded and spoil_permitted — STATUSES on israel_people at the chapters' own day (DJ2; spoil_taken and taken_captive the tape's acts, not this status); the exam's person the soldier who spares the men of a far city taken by siege — barred from it; the one who takes its women captive and its cattle as spoil accepted")
        return out("the siege and the males (20:12-14) — even the warring city was owed the call; the LORD ends the siege; the males smitten, the women and the little ones spared, the spoil eaten — Numbers 31's stricter sentence its own chapter's (the Sifrei 200:4-201:2; midian's %s, %s and %s by CALL, its ask deuteronomy_20 paid here): THE WRITES siege_males_smitten_commanded and spoil_permitted, STATUSES on Israel at the chapters' own day; the soldier who spares the men barred from it" % (MD_MALE[1][0], MD_CAPT[1][0], MD_SPOIL[1][0]), ['siege_males_smitten_commanded', 'spoil_permitted'])
    if ask == 'houses_full_of_every_good_thing':
        ink('20:14', '"and you shall eat THE SPOIL OF YOUR ENEMIES which the LORD your God has given you" — 6:11\'s "houses full of every good thing" the spine\'s reread (201:3); the spoil\'s lemma in the book at 20:14 twice and 2:35, 3:7, 13:17 (the reading\'s lemma assert)')
        move('the Sifrei 201:3 (REREAD from chapter 6)', "'THE SPOIL OF YOUR ENEMIES' — even the swine's flesh and the forbidden foods found in the houses are permitted in the war (Chullin 17a — the English's note, not read); 6:11's 'houses full of every good thing which you did not fill' the same permission at the entry (201:3 — the ink names the verse: a REFERENCE without an edge, the cell's ask not on the shelf of asks the recon lists)")
        dat("the spoil's permission a DATA row citing 6:11 (a reference without an edge — no link of our own); the exam's person the soldier who eats forbidden food from the conquered houses in the war — accepted")
        return out("houses full of every good thing (20:14 with 6:11) — the spoil permitted even to the forbidden foods in the war (the Sifrei 201:3, rereading 6:11; Chullin 17a the note): the soldier who eats of the conquered houses in the war accepted", ['accepted'])
    if ask == 'the_far_cities_and_the_seven':
        ink('20:15-16', '"THUS YOU SHALL DO TO ALL THE CITIES VERY FAR FROM YOU, WHICH ARE NOT OF THE CITIES OF THESE NATIONS; ONLY of the cities of these peoples which the LORD your God gives you for an inheritance YOU SHALL LET NO BREATH LIVE" — "you shall let no breath live" the Bible\'s one seat (the reading\'s formula assert); the negations %s, %s' % (NEG[(20, 15)], NEG[(20, 16)]))
        move('the Sifrei 201:4, 202:1-2 (read whole at the reading); cold_run_seven_nations (CALL) — SN.the_bans_condition = %s' % (SN_COND[1],), "'ALL THE CITIES VERY FAR FROM YOU' — the far cities against the seven: the peace call and the tribute theirs, the ban the seven's (201:4); THE PENITENT NATIONS — the Gibeonites who came, and Joshua's three letters before the entry: who wishes to flee, who wishes to make peace, who wishes to make war (202:1-2 — the Jerusalem Talmud's Sheviit, the English's note, not read; seven_nations' the_bans_condition by CALL: the Canaanite who repents is not devoted — 'exempt')")
        dat("THE WRITE far_cities_scope_declared — a STATUS on israel_people at the chapters' own day (DJ2); THE PARAMETER the_far_cities (the peace and the tribute the far cities'; the ban the seven's); THE DATA ROW the_penitent_nations (Joshua's letters — the Prophets' run citation); the exam's person the Gibeonite who made peace before the war — exempt from the ban (seven_nations' arm)")
        return out("the far cities and the seven (20:15-16) — the far cities' peace and tribute, the seven's ban; the penitent nation accepted, Joshua's letters (the Sifrei 201:4, 202:1-2; seven_nations' %s by CALL): THE WRITE far_cities_scope_declared, a STATUS on Israel at the chapters' own day; the Gibeonite who made peace exempt from the ban" % (SN_COND[1][0],), ['far_cities_scope_declared'])
    if ask == 'no_breath_left_alive':
        ink('20:16-17', '"YOU SHALL LET NO BREATH LIVE; BUT YOU SHALL UTTERLY DEVOTE THEM: the Hittite and the Amorite, the Canaanite and the Perizzite, the Hivite and the Jebusite, AS THE LORD YOUR GOD COMMANDED YOU" — SIX named (the Girgashite absent here; the seven at 7:1 — the reading\'s find); "the Hittite and the Amorite" 20:17\'s Torah seat alone, Joshua 9:1 the closest kin (%d tokens in order shared — the Prophets); "utterly devote" the doubled verb the Bible\'s one seat; THE RECEIPT "as the LORD your God commanded you" — the register\'s one seat in the three chapters (good_land\'s receipt_seats(20) = %s)' % (TWIN['20:17 vs Josh 9:1'], GL_R[1]))
        move('the Sifrei 201:5-202:3 (read whole at the reading); cold_run_seven_nations (CALL) — SN.the_seven_nations(the_seven) = %s, (the_ban) = %s; cold_run_good_land (CALL) — the receipt seat %s' % (SN_SEVEN[1], SN_BAN[1], GL_R[1]), "'YOU SHALL LET NO BREATH LIVE' — the ban's form on the seven (201:5); 'UTTERLY DEVOTE THEM' — the six named and the seventh by 7:1 (seven_nations' seven by CALL — the Girgashite the seventh counted by its own verse); 'AS THE LORD YOUR GOD COMMANDED YOU' — THE RECEIPT: Deuteronomy 7:1-5's line nations_devoted BEHIND on the tape — a RUN CITATION (the pointer's form); the register's class NONE on file retyped at the tail to the class the world says (the register gate's own print); the ban's debit on Israel open to Joshua (seven_nations' row: nations_driven_out 0 and city_devoted 0 on the running world — the acts ahead)")
        dat("THE WRITE nothing_alive_left_commanded — a STATUS on israel_people at the chapters' own day (DJ2); THE RECEIPT 20:17 a DATA row (the referent 7:1-5's line behind; the register's disposition at the tail); the exam's person the soldier who leaves a Hittite of a Canaanite city alive under the ban — barred from it")
        return out("no breath left alive (20:16-17) — the ban on the six named and the seventh of 7:1; 'as He commanded you' the receipt of 7:1-5's line behind, a run citation (the Sifrei 201:5-202:3; seven_nations' %s and %s by CALL; good_land's seat %s): THE WRITE nothing_alive_left_commanded, a STATUS on Israel at the chapters' own day; the soldier who leaves a Hittite alive under the ban barred from it" % (SN_SEVEN[1][0], SN_BAN[1][0], GL_R[1]), ['nothing_alive_left_commanded'])
    if ask == 'that_they_teach_you_not':
        ink('20:18', '"SO THAT THEY TEACH YOU NOT TO DO according to all their abominations which they have done for their gods, and you sin against the LORD your God" — "so that they teach you not" the Bible\'s one seat (the reading\'s formula assert); abominations_learning_barred ONE on israel_people (18:9\'s line) THE TAPE\'S REFERENCE')
        move('the Sifrei 202:4 (read whole at the reading); cold_run_courts_prophet (CALL) — CP.learn_to_understand_not_to_do = %s; cold_run_seven_nations (CALL) — SN.abomination_to_the_lord = %s' % (CP_LEARN[1], SN_ABOM[1]), "'SO THAT THEY TEACH YOU NOT' — the reason of the ban: if they repent and are accepted, they are not killed (202:4 — Sotah 8:1's 'against your enemies' the war's scope; the penitent nation accepted); 18:9's 'you shall not learn to do' the learner's block, this the teacher's (courts_prophet by CALL: to understand you may, to do you may not); 'their abominations for their gods' — 7:25-26's abomination to the LORD (seven_nations by CALL)")
        dat("THE WRITE abominations_teaching_barred — a BLOCK on israel_people at the chapters' own day (DJ2 — the teaching's block beside 18:9's learning's, never a second write of that); the exam's person the Canaanite kept alive who teaches his rite — barred from it")
        return out("that they teach you not (20:18) — the ban's reason; the penitent not killed; the teacher's block beside 18:9's learner's (the Sifrei 202:4; courts_prophet's %s and seven_nations' %s by CALL): THE WRITE abominations_teaching_barred, a BLOCK on Israel at the chapters' own day; the Canaanite who teaches his rite barred from it" % (CP_LEARN[1][0], SN_ABOM[1][0]), ['abominations_teaching_barred'])
    if ask == 'the_trees_of_the_siege':
        ink('20:19-20', '"WHEN YOU BESIEGE A CITY MANY DAYS, to fight against it to take it, YOU SHALL NOT DESTROY ITS TREES by wielding an ax against them, for you may eat of them, and you shall not cut them down; FOR IS THE TREE OF THE FIELD A MAN, to go before you in the siege? ONLY A TREE WHICH YOU KNOW IS NOT A TREE FOR FOOD, it you may destroy and cut down, and build siege works against the city that makes war with you, UNTIL IT FALLS" — "siege" (matzor) at 20:20 and 8:15 in the Torah, 8:15\'s the FLINT rock (the consonants\' homograph — the reading\'s find); "is the tree of the field a man" and "until it falls" the Bible\'s one seat each; "a tree for food" 20:20, Leviticus 19:23 and Ezekiel 47:12; the negations %s' % (NEG[(20, 19)],))
        move('the Sifrei 203:1-10, 204:1-6 (read whole at the reading)', "'WHEN YOU BESIEGE A CITY MANY DAYS' — seizing, not capturing (203:1); the Sabbath's three days: the siege begun three days before the Sabbath continues on it (203:2 — Shabbat 19a the English's note, not read); 'TO FIGHT AGAINST IT' — not to starve it, the channel diverted (203:3); 'DESTROY NOT ITS TREES' — with the ax and with the channel (203:4-6); 'FOR IS THE TREE OF THE FIELD A MAN' — Onkelos's statement 'for the tree of the field is not like a man to come before you in the siege' (the reading's find — the question made a statement); R. Ishmael: the fruit permitted where the tree is not (204:1); 'ONLY A TREE WHICH YOU KNOW IS NOT FOR FOOD' — the barren tree first, then the fruit tree that gives no fruit (204:2-3 — Bava Kamma 91b the note, not read); 'UNTIL IT FALLS' — EVEN ON THE SABBATH (204:5)")
        dat("THE WRITE fruit_tree_cutting_barred — a BLOCK on israel_people at the chapters' own day (DJ2); THE WRITE siege_works_permitted — a STATUS (the barren tree, the works, even on the Sabbath); THE PARAMETER the_trees_rule (the barren first; the fruit tree that gives none; the ax and the channel); the Sabbath's three days a DATA row; the exam's person the besieger who cuts a fruit-bearing tree for a siege work — barred from it; the one who cuts a barren tree accepted")
        return out("the trees of the siege (20:19-20) — seizing many days, the three days before the Sabbath, not by starving; the fruit tree spared from the ax and the channel, Onkelos's 'the tree is not like a man'; the barren tree first, the works until it falls even on the Sabbath (the Sifrei 203:1-204:6): THE WRITES fruit_tree_cutting_barred (a BLOCK) and siege_works_permitted (a STATUS) on Israel at the chapters' own day; the besieger who cuts a fruit tree for a work barred from it", ['fruit_tree_cutting_barred', 'siege_works_permitted'])
    return 'no verdict in span', [], list(P_)


def the_broken_necked_heifer(case, data):
    """F5 — Deut 21:1-9 — ONE LINE heifer_rite_declared writing slain_found_measuring_commanded, heifer_neck_broken_commanded, priests_approach_commanded, elders_hands_washed_commanded and elders_declaration_commanded (STATUSES) and innocent_blood_atoned (a HEAVEN entry — the Holy Spirit's answer); the great court by CALL (courts_prophet), the red cow's yoke, blemish and age by CALL (chukat), the atonement for souls by CALL (incense_shekel), the land's atonement DATA read (refuge); the exam rows Sotah 9:1, 9:2, 9:5, 9:6, 9:9 and Parah 1:1 read whole"""
    del P_[:]
    ask = case['ask']
    if ask == 'when_murderers_multiplied':
        ink('21:1', '"IF ONE IS FOUND SLAIN in the land which the LORD your God gives you to possess, lying in the field, AND IT IS NOT KNOWN WHO SMOTE HIM" — "slain in the land" and "it is not known who smote him" the Bible\'s one seat each (the reading\'s formula assert); 21:1 shares %d tokens in order with 17:2 ("which the LORD your God gives you"); the negation %s' % (TWIN['21:1 vs 17:2'], NEG[(21, 1)]))
        move('the Sifrei 205:1 (read whole at the reading — MISHNAH SOTAH 9:9 CITED IN THE SPINE\'S OWN HEBREW)', "MISHNAH SOTAH 9:9: WHEN MURDERERS MULTIPLIED THE BROKEN-NECKED HEIFER CEASED — when Eliezer ben Dinai came, who was also called Tehinah ben Perishah, and they renamed him 'the murderer's son'; when adulterers multiplied the bitter waters ceased, and R. Yochanan ben Zakkai stopped them (Hosea 4:14 — the Prophets' run citation); when Yose ben Yoezer of Tzeredah and Yose ben Yochanan of Jerusalem died the clusters ceased (Micah 7:1): the rite's cessation the Mishnah's own history — a run citation, the law compiled whole (205:1)")
        dat("THE DATA ROW the_rites_cessation (Sotah 9:9 — the heifer ceased with the murderers, the waters with the adulterers, the clusters with the two Yoses); the exam's person the court in the days of the multiplied murderers that does not bring the heifer — accepted (the rite ceased)")
        return out("when murderers multiplied (21:1) — the broken-necked heifer ceased with Eliezer ben Dinai, the bitter waters with the adulterers, the clusters with the two Yoses (the Sifrei 205:1 = Mishnah Sotah 9:9, cited in the spine's own Hebrew): the court of the multiplied murderers that brings no heifer accepted", ['accepted'])
    if ask == 'slain_on_the_ground_in_the_field':
        ink('21:1', '"IF ONE IS FOUND SLAIN IN THE LAND … LYING IN THE FIELD" — "slain" in the Torah at 21:1, 21:2, 21:3, 21:6 and 32:42 (the reading\'s lemma assert); slain FIVE on the running world (abel, balaam, zimri, cozbi, the kings of Midian — destroy entries) the tape\'s acts, no slain of Israel found')
        move('the Sifrei 205:2-9 (read whole at the reading — MISHNAH SOTAH 9:2 CITED IN THE SPINE\'S OWN HEBREW)', "MISHNAH SOTAH 9:2: hidden in a heap, hanging on a tree, floating on the water — they did not break the neck: 'IN THE LAND' — not hidden in a heap; 'LYING' — not hanging on a tree; 'IN THE FIELD' — not floating on the water; found near the border, near a city mostly gentile, near a city without a court — they did not break; the measuring only to a city with a court; found exactly between two cities — R. Eliezer both bring two heifers; Jerusalem brings none; 'SLAIN' — not strangled (205:2); beyond the Jordan included (205:6); 'IT IS NOT KNOWN WHO SMOTE HIM' — one who saw, even a slave or a woman, cancels the rite (205:8-9 — the English's note; a DATA row)")
        dat("THE PARAMETER the_slain_exclusions (Sotah 9:2 — the heap, the tree, the water; the border, the gentile city, the city without a court; Jerusalem; the two cities); the known killer a DATA row; the exam's person the court of the city nearest to a slain man found hanging on a tree — exempt from the breaking")
        return out("slain on the ground in the field (21:1) — not in a heap, not hanging, not floating; not near the border, the gentile city or the courtless city; Jerusalem never; the seen killer cancels (the Sifrei 205:2-9 = Mishnah Sotah 9:2, cited in the spine's own Hebrew): the nearest court to a slain man hanging on a tree exempt from the breaking", ['exempt'])
    if ask == 'the_measuring_court':
        ink('21:2', '"THEN YOUR ELDERS AND YOUR JUDGES SHALL GO OUT, and they shall measure to the cities around the slain" — "your elders and your judges" the Bible\'s one seat (the reading\'s formula assert); KINC[(21, 2)] EMPTY — no verse in the Bible shares two tokens with 21:2 outside the stop list (the reading\'s kin assert %s)' % (KINC[(21, 2)],))
        move('the Sifrei 205:10-11, 206:1-5 (read whole at the reading); MISHNAH SOTAH 9:1 (the exam row, read whole); cold_run_courts_prophet (CALL) — CP.the_high_court(the_three_courts) = %s' % (CP_COURTS[1],), "MISHNAH SOTAH 9:1: the broken-necked heifer in the holy tongue; 'your elders and your judges shall go out' — THREE OF THE GREAT COURT IN JERUSALEM went out; R. JUDAH says FIVE — 'your elders' two, 'your judges' two, and a court is not even, so they add one: TWO ARMS; the measuring from the nose (206:3 — Sotah 9:4, the ledger's row, not in the twenty-eight); 'to the cities around the slain' — the nearest that has a court (206:4-5; courts_prophet's great court by CALL — the measurers the Chamber of Hewn Stone's)")
        dat("THE WRITE slain_found_measuring_commanded — a STATUS on israel_people at the chapters' own day (DJ2); THE PARAMETER the_measuring_court (Sotah 9:1 — three or five, two arms; the great court's); the exam's person the city's own elders who measure without the great court's three — barred from it")
        return out("the measuring court (21:2) — three of the great court in Jerusalem, or five (R. Judah), in the holy tongue; the nearest city with a court (the Sifrei 205:10-206:5; Mishnah Sotah 9:1; courts_prophet's %s by CALL): THE WRITE slain_found_measuring_commanded, a STATUS on Israel at the chapters' own day; the city's elders who measure without the great court barred from it" % (CP_COURTS[1][0],), ['slain_found_measuring_commanded'])
    if ask == 'the_heifer_never_worked':
        ink('21:3-4', '"and the elders of that city shall take A HEIFER OF THE HERD WHICH HAS NOT BEEN WORKED WITH, WHICH HAS NOT DRAWN A YOKE; and the elders of that city shall bring the heifer down to A ROUGH VALLEY which is neither plowed nor sown, AND SHALL BREAK THE HEIFER\'S NECK there in the valley" — "a heifer of the herd" at 21:3, 1 Samuel 16:2 and Isaiah 7:21; "which has not drawn a yoke" the Bible\'s one seat; "a rough valley" the Bible\'s one seat; the neck-breaking root EIGHT seats in the Bible (21:4, 21:6, 32:2, Exodus 13:13, 34:20, Hosea 10:2, Ruth 1:4, 1:14 — the reading\'s find); 21:3 shares %d tokens in order with Numbers 19:2 ("which … no" the twin); 21:4 shares %d with Exodus 13:13 (the firstling ass); the negations %s, %s' % (TWIN['21:3 vs Num 19:2'], TWIN['21:4 vs Exod 13:13'], NEG[(21, 3)], NEG[(21, 4)]))
        move('the Sifrei 207:1-5 (read whole at the reading); MISHNAH SOTAH 9:5 and PARAH 1:1 (the exam rows, read whole); cold_run_chukat (CALL) — CK.heifer_rite(yoke) = %s, (blemish) = %s, (age) = %s' % (CK_YOKE[1], CK_BLEM[1], CK_AGE[0][:40]), "MISHNAH SOTAH 9:5: the elders of Jerusalem departed; the elders of that city bring A HEIFER OF THE HERD THAT HAS NOT PULLED A YOKE, AND A BLEMISH DOES NOT DISQUALIFY IT (against the red cow, whose blemish disqualifies — chukat's blemish by CALL; the yoke disqualifies both); to a valley eitan (hard) — and even not hard it is valid; they break its neck from behind with a cleaver; its place is forbidden to sow and to work, permitted to comb flax and cut stones; MISHNAH PARAH 1:1: R. Eliezer says the heifer a year old and the cow two years; the sages say the heifer two years and the cow three or four; R. Meir even five; Ben Azzai's 'shelashit' (three years old): TWO ARMS on the age (chukat's age by CALL — the red cow's age the same row's); the firstling ass's neck-breaking Exodus's, not chapter 15's (a DATA row)")
        dat("THE WRITE heifer_neck_broken_commanded — a STATUS on israel_people at the chapters' own day (DJ2); THE PARAMETER the_heifers_fitness (Sotah 9:5 — the yoke disqualifies, a blemish does not; the valley; the cleaver; the place barred); THE PARAMETER the_heifers_age (Parah 1:1 — one year or two, two arms); the exam's person the elders who bring a heifer that once drew a yoke — disqualified (chukat's arm), the rite barred with it")
        return out("the heifer never worked (21:3-4) — the yoke disqualifies and a blemish does not (against the red cow), the valley even not hard, the cleaver from behind, the place barred; the age one year or two (the Sifrei 207:1-5; Mishnah Sotah 9:5, Parah 1:1; chukat's %s, %s and its age by CALL): THE WRITE heifer_neck_broken_commanded, a STATUS on Israel at the chapters' own day; the heifer that drew a yoke disqualified" % (CK_YOKE[1][0], CK_BLEM[1][0]), ['heifer_neck_broken_commanded', 'disqualified'])
    if ask == 'the_priests_the_sons_of_levi':
        ink('21:5', '"AND THE PRIESTS THE SONS OF LEVI SHALL APPROACH, for them the LORD your God has chosen TO MINISTER TO HIM AND TO BLESS IN THE NAME OF THE LORD, and BY THEIR MOUTH shall every dispute and every stroke be" — "the priests the sons of Levi" at 21:5 and 31:9 alone; "to minister to Him and to bless in the name of the LORD" and "every dispute and every stroke" the Bible\'s one seat each (the reading\'s formula assert); 21:5 shares %d tokens in order with 18:5 ("chosen … to minister … in the name of the LORD")' % (TWIN['21:5 vs 18:5'],))
        move('the Sifrei 208:1-4 (read whole at the reading — 208:1 REREAD from chapters 17-18); cold_run_courts_prophet (CALL) — CP.the_levite_who_is_a_priest = %s, CP.the_high_court(the_pairs) = %s' % (CP_LEVITE[1], CP_PAIRS[1]), "'THE PRIESTS THE SONS OF LEVI' — the Levite who is a priest (208:1 = 168:1 — courts_prophet's cell by CALL: the Levite proper barred from the altar); 'FOR THEM THE LORD HAS CHOSEN TO MINISTER AND TO BLESS' — the standing (167:1 at 15b — 18:5's twin); 'BY THEIR MOUTH SHALL EVERY DISPUTE AND EVERY STROKE BE' — the high court's business: the heifer's neck among the pairs at 152:9 (courts_prophet's pairs by CALL — the reading's outside row); Onkelos 'every plague of confinement' (17:8's word — the reading's find) a DATA row")
        dat("THE WRITE priests_approach_commanded — a STATUS on israel_people at the chapters' own day (DJ2); Onkelos's confinement a DATA row; the exam's person the Levite who is not a priest who approaches to bless at the heifer — barred from it (courts_prophet's arm)")
        return out("the priests the sons of Levi (21:5) — the Levite who is a priest; chosen to minister and to bless; every dispute and every stroke by their mouth — the heifer among the pairs (the Sifrei 208:1-4; courts_prophet's %s and %s by CALL): THE WRITE priests_approach_commanded, a STATUS on Israel at the chapters' own day; the Levite who is not a priest barred from the approach" % (CP_LEVITE[1][0], CP_PAIRS[1][0]), ['priests_approach_commanded'])
    if ask == 'our_hands_have_not_shed':
        ink('21:6-7', '"AND ALL THE ELDERS OF THAT CITY, who are nearest to the slain, SHALL WASH THEIR HANDS over the heifer whose neck was broken in the valley; and they shall answer and say: OUR HANDS HAVE NOT SHED THIS BLOOD, NOR HAVE OUR EYES SEEN" — "shall wash their hands" and "our hands have not" the Bible\'s one seat each (the reading\'s formula assert); 21:6 shares %d tokens in order with 21:4 ("the elders of that city"); the written form "shed" with the plural\'s letter and the read form without — the store\'s twelfth token (the reading\'s measure: the ketiv (the written) and the qere (the read)); the negations %s' % (TWIN['21:6 vs 21:4'], NEG[(21, 7)]))
        move('the Sifrei 209:1-2, 210:1-3 (read whole at the reading); MISHNAH SOTAH 9:6 (the exam row, read whole)', "MISHNAH SOTAH 9:6: the elders of that city wash their hands in water at the place of the heifer's breaking and say 'our hands have not shed this blood, nor have our eyes seen' — DID IT ENTER OUR MINDS THAT THE COURT'S ELDERS SHED BLOOD? rather: he did not come to us and we let him go without food, we did not see him and leave him without escort (209:1-2, 210:1-3); 'all the elders of that city' — even a hundred (209:1); the written and the read a DATA row (the reading's measure)")
        dat("THE WRITES elders_hands_washed_commanded and elders_declaration_commanded — STATUSES on israel_people at the chapters' own day (DJ2); THE PARAMETER the_declarations_meaning (Sotah 9:6 — the food and the escort); the written and the read a DATA row; the exam's person the elders who let the traveler go without escort and then declare — accepted, the declaration's meaning the escort")
        return out("our hands have not shed (21:6-7) — the hands washed at the place, the declaration's meaning the food and the escort not withheld; the written and the read (the Sifrei 209:1-210:3; Mishnah Sotah 9:6): THE WRITES elders_hands_washed_commanded and elders_declaration_commanded, STATUSES on Israel at the chapters' own day; the elders who gave escort and declare accepted", ['elders_hands_washed_commanded', 'elders_declaration_commanded'])
    if ask == 'atone_for_your_people':
        ink('21:8-9', '"ATONE FOR YOUR PEOPLE ISRAEL WHOM YOU HAVE REDEEMED, O LORD, and lay not innocent blood in the midst of Your people Israel; AND THE BLOOD SHALL BE ATONED FOR THEM. And you shall purge the innocent blood from your midst, WHEN YOU DO WHAT IS RIGHT IN THE EYES OF THE LORD" — "atone for Your people Israel" the Bible\'s one seat; "whom You have redeemed" 21:8 and 9:26 in the Torah (the reading\'s find — Egypt); "right in the eyes of the LORD" 12:25, 13:19 and 21:9 in the Torah (21:9 sharing %d tokens in order with 12:25); 21:8\'s "atone" the ransom word\'s Torah seat (incense_shekel\'s seats %s); atoned_forgiven SEVEN THE TAPE\'S REFERENCES (Leviticus 4\'s priest\'s atonement — a different effect)' % (TWIN['21:9 vs 12:25'], IS_RANSOM[0][:2]))
        move('the Sifrei 210:4-9 (read whole at the reading); MISHNAH SOTAH 9:6 (the exam row — its close); cold_run_incense_shekel (CALL) — IS_.shekel(atone_souls) = %s; cold_run_refuge (CALL) — RG.DATA[the_lands_atonement] = %s' % (IS_ATONE[0], RG_LAND['value']), "THE PRIESTS SAY 'atone for Your people Israel whom You redeemed, and lay not innocent blood in the midst of Your people' (Onkelos 'the priests shall say' — the subjectless verb given its speaker, the reading's find); AND THEY DID NOT NEED TO SAY 'and the blood shall be atoned for them' — THE HOLY SPIRIT ANNOUNCES IT: when you do so, the blood is atoned for you (Sotah 9:6's close = 210:4-6); 'whom You redeemed' — from Egypt, 9:26's twin (210:7); Exodus 30:15-16's 'to atone for your souls' the ransom's form (incense_shekel by CALL); 'so you shall purge the innocent blood' — F1's innocent_blood_purge_commanded AT ITS SECOND SEAT (the runner's own reference, never a second write); 'when you do what is right' — 12:25's clause (a DATA row citing the twin); the killer found after the breaking dies, not by the heifer's blood (refuge's the_lands_atonement DATA read — Sotah 9:7)")
        dat("THE HEAVEN ENTRY innocent_blood_atoned — on israel_people at the chapters' own day (DJ2 — the Holy Spirit's answer); the priests' saying a DATA row (Onkelos); 9:26's redemption a DATA row; the purge formula's second seat of the third form a reference; the exam's person the community whose elders did so — the blood atoned for them: the heaven entry's own case")
        return out("atone for Your people (21:8-9) — the priests say it, the Holy Spirit answers it: when you do so, the blood is atoned; redeemed from Egypt; the innocent blood purged at its second seat; the killer found after dies (the Sifrei 210:4-9; Mishnah Sotah 9:6; incense_shekel's %s and refuge's %s by CALL): THE HEAVEN ENTRY innocent_blood_atoned on Israel at the chapters' own day; the community that did so atoned" % (IS_ATONE[0][0], RG_LAND['value']), ['innocent_blood_atoned'])
    return 'no verdict in span', [], list(P_)


def the_captive(case, data):
    """F6 — Deut 21:10-14 — ONE LINE captive_wife_declared writing captive_wife_permitted, captive_mourning_month_commanded and captive_release_commanded (STATUSES) and captive_sale_barred (a BLOCK); Midian's captives by CALL (midian), Hagar's humbling by CALL (primeval); the month a PARAMETER (the calendar's month, no timer — no captive on the tape); the disputed rows (the first act, the nails, the mourning) DATA with their arms"""
    del P_[:]
    ask = case['ask']
    if ask == 'when_you_go_out_to_war_the_second':
        ink('21:10', '"WHEN YOU GO OUT TO WAR AGAINST YOUR ENEMIES, and the LORD your God gives them into your hand, AND YOU TAKE THEM CAPTIVE" — 20:1\'s opening verbatim (21:10 shares %d tokens in order with 20:1 — the reading\'s twin assert; the closest kin %s); taken_captive THREE (lot, israel_people, the_captives_of_midian) and captives_and_spoil_taken at Numbers 31:9-12 THE TAPE\'S REFERENCES' % (TWIN['21:10 vs 20:1'], KINC[(21, 10)][0]))
        move('the Sifrei 211:1-2 (read whole at the reading); cold_run_midian (CALL) — MD.the_war(captives) = %s, MD.the_sentence(every_female_kept) = %s' % (MD_CAPT[1], MD_FEMALE[1]), "'WHEN YOU GO OUT TO WAR' — the optional war: 'against your enemies', not the seven whose women are devoted (211:1); 'AND YOU TAKE THEM CAPTIVE' — the captives of Midian the tape's own captives (midian by CALL: the women taken captive at Numbers 31:9, the females sentenced at 31:17-18 — the captive woman's law this chapter's, the sentence that chapter's); 'them' — even the Canaanites among them in a far city (211:2)")
        dat("the war's scope a DATA row (the optional war; the captives the tape's acts — the references, never a second act); the exam's person the soldier of an optional war who takes captives — accepted (the acts on the tape; this law the captive woman's)")
        return out("when you go out to war — the second (21:10) — 20:1's opening verbatim; the optional war's captives, the tape's own at Numbers 31:9 (the Sifrei 211:1-2; midian's %s by CALL): the soldier of an optional war who takes captives accepted" % (MD_CAPT[1][0],), ['accepted'])
    if ask == 'a_woman_of_beautiful_form':
        ink('21:11', '"AND YOU SEE AMONG THE CAPTIVES A WOMAN OF BEAUTIFUL FORM, AND YOU DESIRE HER, and would take her for a wife" — "a woman of beautiful form" the Bible\'s one seat, "beautiful of form" Rachel\'s phrase (Genesis 29:17 — the reading\'s find: %d shared); the parser silent at 21:11' % (TWIN['21:11 vs Gen 29:17'],))
        move('the Sifrei 211:3-5, 212:1 (read whole at the reading)', "'A WOMAN' — even a married woman (211:3); 'AMONG THE CAPTIVES' — one, not two (211:5); 'AND YOU DESIRE HER' — even if she is not beautiful (211:4); 'AND WOULD TAKE HER FOR A WIFE' — THE TORAH SPOKE ONLY AGAINST THE EVIL INCLINATION: better that Israel eat the flesh of dying beasts slaughtered than the flesh of carrion (212:1); the first act's permission disputed — in the war or after the month (Kiddushin 21b-22a — the English's note, not read: the arms on the ledger's row)")
        dat("THE WRITE captive_wife_permitted — a STATUS on israel_people at the chapters' own day (DJ2); THE PARAMETER the_first_act (Kiddushin 21b-22a — two arms); the exam's person the soldier who takes one captive woman, even a married one, for a wife — accepted under the permission")
        return out("a woman of beautiful form (21:11) — even a married woman, one not two, even not beautiful; the Torah against the evil inclination; the first act disputed (the Sifrei 211:3-5, 212:1; Rachel's phrase): THE WRITE captive_wife_permitted, a STATUS on Israel at the chapters' own day; the soldier who takes one captive woman accepted", ['captive_wife_permitted'])
    if ask == 'the_head_the_nails_the_garment':
        ink('21:12-13', '"then you shall bring her into your house, AND SHE SHALL SHAVE HER HEAD AND DO HER NAILS; and she shall put off THE GARMENT OF HER CAPTIVITY from her, and shall sit in your house AND BEWAIL HER FATHER AND HER MOTHER A MONTH OF DAYS; and after that you shall go in to her and be her husband, and she shall be your wife" — "and she shall shave her head" and "the garment of her captivity" the Bible\'s one seat each; "a month of days" at 21:13 and 2 Kings 15:13 (Shallum\'s reign — the reading\'s find); 21:12\'s one kin 22:2 (%s)' % (KINC[(21, 12)],))
        move('the Sifrei 212:2-4, 213:1-8 (read whole at the reading)', "'SHE SHALL SHAVE HER HEAD' — that she be ugly in his eyes (212:2); 'AND DO HER NAILS' — R. ELIEZER she cuts them, R. AKIVA she lets them grow: TWO ARMS — ONKELOS 'let her nails grow' AFTER R. AKIVA (the reading's find; Yevamot 48a the English's note, not read); 'THE GARMENT OF HER CAPTIVITY' — the idolaters' daughters adorn themselves in war to lead astray (213:2); 'SHE SHALL SIT IN YOUR HOUSE' — where he goes in and out, that he see her weeping and be repelled (213:3-4); 'AND BEWAIL HER FATHER AND HER MOTHER' — R. AKIVA: her idolatry, 'saying to the wood, you are my father' (Jeremiah 2:27 — the Prophets' run citation): TWO ARMS; 'A MONTH OF DAYS' — thirty days; R. Simeon ben Eleazar three months (213:6-8 — the English's note): the month the calendar's key read, no timer set (no captive on the tape)")
        dat("THE WRITE captive_mourning_month_commanded — a STATUS on israel_people at the chapters' own day (DJ2); THE PARAMETER the_captives_acts (the head, the nails — two arms, the garment, the sitting); THE PARAMETER the_month_of_days (thirty days; three months — the calendar's month, no timer); the exam's person the man who goes in to her before the month — barred from it")
        return out("the head, the nails, the garment (21:12-13) — shaved to be ugly; the nails cut or grown (two arms — Onkelos after R. Akiva); the garment of her captivity put off; the weeping seen; her parents or her idolatry bewailed; a month of days (the Sifrei 212:2-213:8): THE WRITE captive_mourning_month_commanded, a STATUS on Israel at the chapters' own day; the man who goes in before the month barred from it", ['captive_mourning_month_commanded'])
    if ask == 'if_you_delight_not_in_her':
        ink('21:14', '"AND IT SHALL BE, IF YOU DELIGHT NOT IN HER, then you shall SEND HER AWAY FOR HERSELF; but YOU SHALL SURELY NOT SELL HER FOR MONEY, you shall not deal with her as a slave, SINCE YOU HAVE HUMBLED HER" — "send her away for herself", "sell her for money", "deal with her as a slave" and "you have humbled her" the Bible\'s one seat each (the reading\'s formula assert); 21:14 shares %d tokens in order with 24:1\'s divorce; the negations %s' % (TWIN['21:14 vs 24:1'], NEG[(21, 14)]))
        move('the Sifrei 214:1-6, 215:1-3 (read whole at the reading); cold_run_primeval (CALL) — PV.hagar(affliction_reading) = %s, effect %s' % (PV_HAGAR[0], PV_HAGAR[2]), "'IF YOU DELIGHT NOT IN HER' — the Torah tells you that you will hate her (214:1); 'SEND HER AWAY FOR HERSELF' — with a divorce document (214:2-3 — 24:1's form: the release a divorce, the reading's crown; a DATA row citing 24:1 ahead, the family runner's purchase not called); 'YOU SHALL SURELY NOT SELL HER' — the doubled verb, the sale barred whether he took her or not (215:1); 'NOR DEAL WITH HER AS A SLAVE' — Onkelos 'you shall not trade in her' (2:5's 'trade' — the reading's find; 215:2); 'SINCE YOU HAVE HUMBLED HER' — Genesis 16:6's word on Hagar (primeval's affliction reading by CALL — Sarai's humbling the word's first seat; 215:3)")
        dat("THE WRITES captive_release_commanded (a STATUS) and captive_sale_barred (a BLOCK) — on israel_people at the chapters' own day (DJ2); the divorce's form a DATA row citing 24:1 ahead (no pointer row — the ink's own citation, no receipt); Onkelos's trading a DATA row; the exam's person the man who sells his captive wife for money — barred from it")
        return out("if you delight not in her (21:14) — sent away with a divorce document, never sold, never traded; humbled — Hagar's word (the Sifrei 214:1-215:3; primeval's %s by CALL): THE WRITES captive_release_commanded (a STATUS) and captive_sale_barred (a BLOCK) on Israel at the chapters' own day; the seller of his captive wife barred from it" % (PV_HAGAR[0],), ['captive_release_commanded', 'captive_sale_barred'])
    return 'no verdict in span', [], list(P_)
